// Validate required fields
const requiredFields = ['submissionId', 'timestamp', 'contact', 'answers'];
const missingFields = [];

requiredFields.forEach(field => {
  if (!item.json[field]) {
    missingFields.push(field);
  }
});

if (missingFields.length > 0) {
  return {
    json: {
      error: true,
      message: 'Missing required fields',
      missingFields
    }
  };
}

// Validate contact.email format
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(item.json.contact.email)) {
  return {
    json: {
      error: true,
      message: 'Invalid email format'
    }
  };
}

// Validate answers.q3 is number 1-10
if (typeof item.json.answers.q3 !== 'number' || item.json.answers.q3 < 1 || item.json.answers.q3 > 10) {
  return {
    json: {
      error: true,
      message: 'Budget readiness (q3) must be a number between 1 and 10'
    }
  };
}

return item;

// STUB SCORING MODEL - Replace with NEU-5 implementation
const answers = item.json.answers;

// Fixture scoring logic (for testing until NEU-5 is ready)
let score = 0;

// Q1: AI maturity (explorer=10, experimenting=30, scaling=60, optimized=80)
const q1Scores = { explorer: 10, experimenting: 30, scaling: 60, optimized: 80 };
score += q1Scores[answers.q1] || 0;

// Q3: Budget readiness (1-10 scale, multiply by 5)
score += (answers.q3 || 0) * 5;

// Q4: Timeline (immediate=20, 1-3 months=15, 3-6 months=10, 6+ months=5)
const q4Scores = { immediate: 20, '1-3 months': 15, '3-6 months': 10, '6+ months': 5 };
score += q4Scores[answers.q4] || 0;

// Q5: Decision authority (decision_maker=15, influencer=10, researcher=5)
const q5Scores = { decision_maker: 15, influencer: 10, researcher: 5 };
score += q5Scores[answers.q5] || 0;

// Cap score at 100
score = Math.min(score, 100);

// Determine band
let band;
if (score >= 70) {
  band = 'HIGH';
} else if (score >= 40) {
  band = 'MEDIUM';
} else {
  band = 'LOW';
}

return {
  json: {
    ...item.json,
    score,
    band,
    scoringNotes: 'STUB: Replace with NEU-5 model'
  }
};

// Add Calendly scheduling link for HIGH and MEDIUM bands
const calendlyBaseUrl = 'https://calendly.com/neural-studio-lab/strategy-call';

return {
  json: {
    ...item.json,
    schedulingLink: calendlyBaseUrl,
    qualifiesForCall: true
  }
};
